const B64="";
const HTML=Buffer.from(B64,'base64').toString('utf8');
const FP='yanni-sushi',FA='AIzaSyD-Qm_-JIMb5NSdow7RDAcd6PGZLDX0org';

async function buscaRef(ref){
  const r=await fetch(`https://firestore.googleapis.com/v1/projects/${FP}/databases/(default)/documents:runQuery?key=${FA}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({structuredQuery:{from:[{collectionId:'pedidos'}],where:{fieldFilter:{field:{fieldPath:'referencia'},op:'EQUAL',value:{stringValue:ref}}},limit:1}})});
  const d=await r.json();
  if(d[0]&&d[0].document){const p=d[0].document.name.split('/');return p[p.length-1];}
  return null;
}
async function atualizaPedido(id,dados){
  const fields={};
  for(const[k,v]of Object.entries(dados)){
    if(typeof v==='string')fields[k]={stringValue:v};
    else if(typeof v==='number')fields[k]={doubleValue:v};
    else if(typeof v==='boolean')fields[k]={booleanValue:v};
  }
  const mask=Object.keys(dados).map(k=>`updateMask.fieldPaths=${k}`).join('&');
  await fetch(`https://firestore.googleapis.com/v1/projects/${FP}/databases/(default)/documents/pedidos/${id}?${mask}&key=${FA}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({fields})});
}
module.exports=async(req,res)=>{
  res.setHeader('Access-Control-Allow-Origin','*');
  res.setHeader('Access-Control-Allow-Methods','POST,GET,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers','Content-Type');
  if(req.method==='OPTIONS')return res.status(200).end();
  const p=req.url.split('?')[0];
  if(req.method==='GET'&&(p==='/'||p===''||p==='/index.html')){
    res.setHeader('Content-Type','text/html; charset=utf-8');
    return res.status(200).send(HTML);
  }
  if(req.method==='POST'&&p==='/webhook'){
    try{const b=req.body;const st=b.status||b.payment_status||'';const oid=b.order_id||b.id||b.reference||'';const val=(b.amount||b.paid_amount||0)/100;if(['approved','paid','APPROVED','PAID'].includes(st)){const pid=await buscaRef(oid);if(pid){await atualizaPedido(pid,{status:'pago',statusPagamento:'aprovado',pagoEm:new Date().toISOString(),valorPago:val,infinitePayOrderId:oid});return res.status(200).json({ok:true,pid});}}return res.status(200).json({ok:true});}catch(e){return res.status(500).json({erro:e.message});}
  }
  if(req.method==='POST'&&p==='/suki-painel'){
    try{const{pergunta}=req.body;const r=await fetch('https://api.groq.com/openai/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+process.env.GROQ_API_KEY},body:JSON.stringify({model:'llama-3.3-70b-versatile',messages:[{role:'system',content:'Você é Suki, assistente do Yanni Sushi de Alegrete-PI. Responda em português, máximo 3 linhas.'},{role:'user',content:pergunta}],max_tokens:400})});const d=await r.json();return res.status(200).json({resposta:d.choices?.[0]?.message?.content||'Suki offline.'});}catch(e){return res.status(500).json({erro:e.message});}
  }
  if(req.method==='GET'&&p==='/status')return res.status(200).json({ok:true});
  return res.status(404).json({erro:'404'});
};
